def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=grid[0][0]
    markers={v for row in grid for v in row if v != bg}
    # ARC examples use one foreground color and one fill color; infer each from non-bg
    mark=next(iter(markers))
    fill=3
    out=[r[:] for r in grid]
    for r,row in enumerate(grid):
        inds=[c for c,v in enumerate(row) if v==mark]
        if len(inds)>=2:
            for c in range(min(inds)+1,max(inds)):
                if grid[r][c]==bg: out[r][c]=fill
    for c in range(w):
        inds=[r for r in range(h) if grid[r][c]==mark]
        if len(inds)>=2:
            for r in range(min(inds)+1,max(inds)):
                if grid[r][c]==bg: out[r][c]=fill
    return out
